#!/usr/bin/env python3
from __future__ import annotations
import json
from datetime import datetime, timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
STATE=ROOT/'STATE.json'; QUEUE=ROOT/'WORK_QUEUE.json'

def now(): return datetime.now(timezone.utc).isoformat()
def load(p): return json.loads(Path(p).read_text(encoding='utf-8'))
def save(p,o):
    p=Path(p); p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def append_jsonl(p,o):
    with Path(p).open('a',encoding='utf-8') as f: f.write(json.dumps(o,ensure_ascii=False)+'\n')
def patch_once(path,old,new,label):
    p=Path(path); text=p.read_text(encoding='utf-8')
    if new in text: return
    if old not in text: raise SystemExit(f'HARD STOP: missing patch anchor {label}')
    p.write_text(text.replace(old,new,1),encoding='utf-8')

def patch_controller():
    p=ROOT/'tools/rfc.py'
    old='''    for name in [\n        "RUN_PLAN.md", "SOURCE_REGISTER.json", "PRE_EXECUTION_LOCK.json", "ENVIRONMENT.json",\n        "CHECKPOINT_RECORD.json", "GENERATED_OUTPUT_MANIFEST.json", "REPLAY_RECORD.json",\n        "GATE_RESULTS.json", "INDEPENDENT_VERIFICATION.md", "CLOSEOUT.md"\n    ]:\n        copy_template(name, dest / name)\n    (dest / "FAILURES.jsonl").write_text("", encoding="utf-8")\n'''
    new='''    for name in [\n        "RUN_PLAN.md", "SOURCE_REGISTER.json", "PRE_EXECUTION_LOCK.json", "ENVIRONMENT.json",\n        "CHECKPOINT_RECORD.json", "GENERATED_OUTPUT_MANIFEST.json", "REPLAY_RECORD.json",\n        "GATE_RESULTS.json", "INDEPENDENT_VERIFICATION.md", "CLOSEOUT.md"\n    ]:\n        copy_template(name, dest / name)\n    if args.module in load_json(ROOT / "config/module_graph.json")["module_order"]:\n        spec = load_json(ROOT / "modules" / args.module / "spec.json")\n        save_json(dest / "OUTPUT_CONTRACT.json", {\n            "schema_version":"1.0","run_id":run_id,"module":args.module,"status":"DRAFT",\n            "required_outputs":[{"name":n,"status":"UNSATISFIED","artifact_paths":[],"semantic_gate":"PENDING","independent_verification":"PENDING","child_ready":False} for n in spec.get("required_outputs",[])],\n            "child_bindings":{},\n            "note":"PASS requires every module-spec output and configured child binding to be artifact-backed, semantically verified, independently verified, and child-ready."\n        })\n    (dest / "FAILURES.jsonl").write_text("", encoding="utf-8")\n'''
    patch_once(p,old,new,'new-run output contract')
    marker='''def cmd_close_run(args: argparse.Namespace) -> int:\n'''
    helper='''def validate_required_output_contract(path: Path, module: str) -> tuple[bool, list[str]]:\n    errors=[]; cp=path/"OUTPUT_CONTRACT.json"\n    if not cp.exists(): return False,["OUTPUT_CONTRACT.json is missing"]\n    spec=load_json(ROOT/"modules"/module/"spec.json"); c=load_json(cp)\n    if c.get("status")!="PASS": errors.append("OUTPUT_CONTRACT status must be PASS")\n    required=list(spec.get("required_outputs",[])); by={r.get("name"):r for r in c.get("required_outputs",[]) if isinstance(r,dict)}\n    if set(by)!=set(required): errors.append(f"required-output names differ from spec: expected {required}; found {sorted(x for x in by if x)}")\n    for name in required:\n        r=by.get(name)\n        if not r: errors.append(f"missing required output: {name}"); continue\n        if r.get("status")!="SATISFIED": errors.append(f"required output not SATISFIED: {name}")\n        if r.get("semantic_gate")!="PASS": errors.append(f"semantic gate not PASS: {name}")\n        if r.get("independent_verification")!="PASS": errors.append(f"independent verification not PASS: {name}")\n        if r.get("child_ready") is not True: errors.append(f"required output not child-ready: {name}")\n        arts=r.get("artifact_paths",[])\n        if not arts: errors.append(f"required output has no artifacts: {name}")\n        for rel in arts:\n            q=(ROOT/rel).resolve()\n            if not q.exists() or ROOT not in q.parents: errors.append(f"required-output artifact missing/outside repository: {name}: {rel}")\n    cfgp=ROOT/"config/required_output_contracts.json"; cfg=load_json(cfgp) if cfgp.exists() else {}\n    bindings=c.get("child_bindings",{})\n    for req in cfg.get("modules",{}).get(module,{}).get("required_child_bindings",[]):\n        name=req["name"]; r=bindings.get(name)\n        if not isinstance(r,dict): errors.append(f"missing child binding: {name}"); continue\n        if r.get("status")!="SATISFIED": errors.append(f"child binding not SATISFIED: {name}")\n        if r.get("source_lineage")!="PASS": errors.append(f"child binding source lineage not PASS: {name}")\n        if r.get("independent_verification")!="PASS": errors.append(f"child binding independent verification not PASS: {name}")\n        if not r.get("artifact_paths"): errors.append(f"child binding has no artifact paths: {name}")\n        if not req.get("allow_derived_absence",False) and r.get("derived_absence") is True: errors.append(f"child binding cannot be satisfied by absence: {name}")\n        if req.get("allow_derived_absence",False) and r.get("derived_absence") is True and not r.get("absence_proof_artifact"): errors.append(f"derived absence lacks proof artifact: {name}")\n    return not errors,errors\n\n\n'''
    patch_once(p,marker,helper+marker,'output contract validator')
    old2='''        run_module = load_json(path / "run.json").get("module")\n        if run_module in set(load_json(ROOT / "config/module_graph.json")["module_order"]) | {"UNIVERSE", "FINAL"}:\n'''
    new2='''        run_module = load_json(path / "run.json").get("module")\n        module_order = set(load_json(ROOT / "config/module_graph.json")["module_order"])\n        if run_module in module_order:\n            output_ok, output_errors = validate_required_output_contract(path, run_module)\n            if not output_ok:\n                print("PASS requires a complete required-output and child-readiness contract", file=sys.stderr)\n                for err in output_errors: print(f"- {err}", file=sys.stderr)\n                return 2\n        if run_module in module_order | {"UNIVERSE", "FINAL"}:\n'''
    patch_once(p,old2,new2,'close-run output contract')
    marker2='''def cmd_record_claim(args: argparse.Namespace) -> int:\n'''
    reopen='''def cmd_reopen_module(args: argparse.Namespace) -> int:\n    state=load_json(STATE_PATH)\n    if args.module not in state.get("modules",{}): print("unknown module",file=sys.stderr); return 2\n    item=active_item()\n    if item.get("module")!=args.module: print(f"active work unit {item.get('id')} does not authorize reopening {args.module}",file=sys.stderr); return 2\n    rec=state["modules"][args.module]; cur=rec.get("evidence_state"); fid=rec.get("fidelity")\n    if cur not in {"FROZEN","BLOCKED"}: print("only FROZEN/BLOCKED modules may be reopened",file=sys.stderr); return 2\n    if args.fidelity not in FIDELITY_ORDER or fid not in FIDELITY_ORDER: print("invalid fidelity",file=sys.stderr); return 2\n    if cur=="FROZEN" and FIDELITY_ORDER.index(args.fidelity)<=FIDELITY_ORDER.index(fid): print("frozen-module repair must target strictly higher fidelity",file=sys.stderr); return 2\n    ev=(ROOT/args.evidence).resolve()\n    if not ev.exists() or ROOT not in ev.parents: print("reopen evidence must exist inside repository",file=sys.stderr); return 2\n    old={"evidence_state":cur,"fidelity":fid}; rec["evidence_state"]="DESIGN"; rec["fidelity"]=args.fidelity; rec["active_run"]=None; rec["reopened_from"]=old; rec["reopen_evidence"]=str(ev.relative_to(ROOT))\n    rec.setdefault("evidence_history",[]).append({"state":"DESIGN","fidelity":args.fidelity,"evidence":str(ev.relative_to(ROOT)),"timestamp_utc":now(),"work_unit":item["id"],"reopened_from":old})\n    state["last_updated_utc"]=now(); save_json(STATE_PATH,state)\n    decision={"decision_id":f"REOPEN-{args.module}-{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}","timestamp_utc":now(),"work_unit":item["id"],"decision":f"Reopened {args.module} from {cur}/{fid} for a versioned higher-fidelity superseding replay.","basis":[str(ev.relative_to(ROOT))],"alternatives_rejected":["overwrite frozen evidence","fabricate missing child outputs downstream"],"changes_science":False,"required_replay":item["id"],"commit_sha":state.get("last_verified_commit") or ""}\n    with (ROOT/"memory/DECISION_LOG.jsonl").open("a",encoding="utf-8") as f: f.write(json.dumps(decision,ensure_ascii=False)+"\\n")\n    print(json.dumps(decision,indent=2)); return 0\n\n\n'''
    patch_once(p,marker2,reopen+marker2,'reopen command')
    old3='''    sp = sub.add_parser("close-run")\n'''
    new3='''    sp = sub.add_parser("reopen-module")\n    sp.add_argument("module")\n    sp.add_argument("--fidelity", required=True)\n    sp.add_argument("--evidence", required=True)\n    sp.set_defaults(func=cmd_reopen_module)\n\n    sp = sub.add_parser("close-run")\n'''
    patch_once(p,old3,new3,'reopen parser')

