def patch_recipes():
    for m,label in [("B","required output completeness and C child-readiness"),("C","required output completeness and D child-readiness"),("D","required output completeness and E child-readiness"),("E","required output completeness and F child-readiness"),("F","required output completeness and G child-readiness")]:
        gp=ROOT/f'recipes/{m}/gates.json'; g=load(gp)
        if label not in [x.get('gate') for x in g.get('componentwise',[])]: g.setdefault('componentwise',[]).append({'gate':label,'required':'PASS'})
        save(gp,g)
        rp=ROOT/f'recipes/{m}/recipe.json'; r=load(rp)
        if label not in r.get('mandatory_gates',[]): r.setdefault('mandatory_gates',[]).append(label)
        r['child_readiness_contract']=f'config/required_output_contracts.json#modules.{m}'
        r['closure_rule']='A lower-fidelity or partial subresult may be preserved, but canonical PASS/advance requires all module-spec outputs and child bindings.'
        stop='any module-spec required output or configured child binding is missing, unverified, or not child-ready'
        if stop not in r.get('hard_stop_conditions',[]): r.setdefault('hard_stop_conditions',[]).append(stop)
        save(rp,r)

