def update_queue_state():
    state=load(STATE); q=load(QUEUE); items=q['items']; by={x['id']:x for x in items}
    if state.get('active_work_unit')!='G-160' or state.get('current_run') is not None: raise SystemExit('HARD STOP: close current G run BLOCKED before lineage transition')
    chain=[
      ("B-115","Repair Module B: Complete Four-Sector Genesis Handoff","B",["B-110"],"Reconstruct and verify the exact four-sector genesis partition and a complete child-ready B->C parent from the already executed Big-Implosion state, without changing the Big-Implosion law.","PRODUCTION"),
      ("C-125","Replay Module C: Full Microscopic Constitution","C",["B-115"],"Replay the recovered triad-derived microscopic construction on the repaired B parent and execute the full child-ready microscopic/prethermal state.","PRODUCTION"),
      ("D-135","Replay Module D: Full Thermal and Phase History","D",["C-125"],"Replay nonequilibrium transport, phase chronology, radiation/neutrino/charged-species evolution and nuclear readiness from the repaired C parent.","PRODUCTION"),
      ("E-145","Replay Module E: Full Primordial Nuclear State","E",["D-135"],"Replay the source-owned isotope-resolved nuclear network and export the complete plasma/radiation-ready E parent.","PRODUCTION"),
      ("F-155","Replay Module F: Child-Ready Plasma, Radiation and Opacity","F",["E-145"],"Replay post-nuclear plasma/radiation persistence and derive the source-owned ionization, charge, opacity, transport and atomic-candidate state required by G.","PRODUCTION")]
    insert_at=next(i for i,x in enumerate(items) if x['id']=='G-160')
    for rid,title,mod,deps,obj,fid in reversed(chain):
        if rid not in by:
            rec={"id":rid,"title":title,"module":mod,"status":"BLOCKED","depends_on":deps,"objective":obj,"steps":["Read the active packet, exact repaired parent, module spec/recipe, recovered REPLAY_REQUIRED derivation and source-traceability files.","Freeze exact source bytes, parent hashes, definitions, output contract, child bindings, tests, gates, falsifiers and claim boundary before primary execution.","Re-derive from current exact parent; old formal objects are candidate derivations, never inherited PASS.","Execute the complete parent-driven physical state at the required fidelity.","Run semantic countermodels, convergence, covariance, restart, clean replay and independent reconstruction.","Freeze a versioned handoff only if OUTPUT_CONTRACT and all componentwise gates PASS."],"deliverables":[f"modules/{mod}/runs/<RUN_ID>/OUTPUT_CONTRACT.json",f"modules/{mod}/runs/<RUN_ID>/GATE_RESULTS.json",f"modules/{mod}/runs/<RUN_ID>/INDEPENDENT_VERIFICATION.md",f"modules/{mod}/runs/<RUN_ID>/CLOSEOUT.md",f"versioned {mod} child handoff"],"gates":["all module required outputs SATISFIED","all configured child bindings SATISFIED","generation firewall sealed","componentwise scientific gates PASS","clean replay/restart/independent reconstruction PASS"],"commit_message":f"Repair Module {mod} with the full child-ready triadic state","required_evidence_state":"FROZEN","required_fidelity":fid}
            items.insert(insert_at,rec); by[rid]=rec
    for rid,_,_,_,_,_ in chain: by[rid]['status']='BLOCKED'
    by['B-115']['status']='ACTIVE'; by['G-160']['status']='BLOCKED'; by['G-160']['depends_on']=['F-155']
    state['active_work_unit']='B-115'; state['current_module']='B'; state['current_run']=None; state['project_status']='ACTIVE'
    g=state['modules']['G']; g['evidence_state']='BLOCKED'; g['fidelity']='UNSTARTED'; g['active_run']=None
    if not any(h.get('state')=='BLOCKED' and h.get('evidence')=='modules/G/runs/G-160-20260808T021341Z/G_DERIVATION_OBSTRUCTION.json' for h in g.setdefault('evidence_history',[])):
        g['evidence_history'].append({'state':'BLOCKED','fidelity':'UNSTARTED','evidence':'modules/G/runs/G-160-20260808T021341Z/G_DERIVATION_OBSTRUCTION.json','timestamp_utc':now(),'work_unit':'G-160'})
    state['strongest_supported_claim']='A through F retain their previously executed lower-fidelity results at their explicit scopes. The exhaustive repair audit recovered the stronger triadic B-G derivation lineage and proved the first canonical handoff loss occurs at B->C, where the complete four-sector genesis partition was omitted despite being reconstructible from the executed B bytes.'
    state['strongest_unsupported_claim']='The repaired full microscopic, thermal, nuclear, plasma/radiation and recombination chain has not yet been re-executed from the superseding B parent; current reduced B-F handoffs must not be used as complete canonical parents for that claim.'
    state['last_updated_utc']=now(); save(QUEUE,q); save(STATE,state)
    claims=load(ROOT/'CLAIMS_LEDGER.json')
    for c in claims.get('claims',[]):
        if c.get('owner') in {'D','E','F'}:
            c['canonical_parent_status']='PRESERVED_LOWER_FIDELITY_SUBRESULT_PENDING_SUPERSEDING_REPLAY'; c['child_ready']=False; c['scope_note']='Original claim remains supported only at its explicit MINIMAL_SPINE scope; it is not the complete canonical parent for the superseding B-G replay chain.'
    save(ROOT/'CLAIMS_LEDGER.json',claims)

def add_docs_tests():
    (ROOT/'docs/28_REQUIRED_OUTPUT_AND_CHILD_READINESS_PROTOCOL.md').write_text('# Required Output and Child-Readiness Protocol\n\nA numerical or algebraic PASS is necessary but not sufficient for physical module closure. Every `spec.json` required output must be artifact-backed, semantically PASS, independently verified and child-ready in `OUTPUT_CONTRACT.json`. Configured parent-to-child bindings are equally mandatory. Lower-fidelity subresults remain valid at their earned scope but cannot replace a missing parent object. `UNASSIGNED`, `NOT_DERIVED`, readiness scores, manufactured examples or generic internal hazards do not satisfy a required child binding unless the contract explicitly permits and proves a derived absence. Public targets and remembered textbook constants remain forbidden generation inputs.\n',encoding='utf-8')
    (ROOT/'tests/test_child_readiness_contract.py').write_text("""from pathlib import Path\nimport json,unittest\nR=Path(__file__).resolve().parents[1]\nclass TestChildReadiness(unittest.TestCase):\n def test_controller_enforces_contract(self):\n  t=(R/'tools/rfc.py').read_text(); self.assertIn('validate_required_output_contract',t); self.assertIn('OUTPUT_CONTRACT.json',t)\n def test_b_to_f_contracts_present(self):\n  c=json.loads((R/'config/required_output_contracts.json').read_text()); self.assertTrue({'B','C','D','E','F','G'}<=set(c['modules']))\n def test_f_requires_physical_opacity(self):\n  c=json.loads((R/'config/required_output_contracts.json').read_text()); names={x['name'] for x in c['modules']['F']['required_child_bindings']}; self.assertIn('opacity_law',names); self.assertIn('radiation_state',names)\nif __name__=='__main__': unittest.main()\n""",encoding='utf-8')

